///|
pub suberror ConfigError {
  InvalidConfig(String)
} derive(Debug)

///|
pub enum Connection {
  Server
  Ssh
} derive(Eq, Debug)

///|
pub struct Settings {
  connection : Connection
  command : Array[String]
  home : String?
  context : String?
  build_ref : String?
  up_args : Array[String]
  codex_auth : Bool
  idle_timeout_ms : Int64?
  idle_timeout_source : String?
} derive(Eq, Debug)

///|
fn string_field(
  value : Json,
  name : String,
  location : String,
) -> String? raise ConfigError {
  match field(value, name) {
    None => None
    Some(Json::String(text)) => Some(text)
    _ => raise InvalidConfig("\{location}.\{name} must be a string")
  }
}

///|
fn object_field(
  value : Json,
  name : String,
  location : String,
) -> Json raise ConfigError {
  match field(value, name) {
    None => Json::empty_object()
    Some(Json::Object(_) as object) => object
    _ => raise InvalidConfig("\{location}.\{name} must be a mapping")
  }
}

///|
fn args_field(
  value : Json,
  location : String,
) -> Array[String] raise ConfigError {
  match field(value, "upArgs") {
    None => []
    Some(Json::Array(items)) =>
      items.map(item => {
        match item {
          Json::String(text) => text
          _ => raise InvalidConfig("\{location}.upArgs must contain strings")
        }
      })
    _ => raise InvalidConfig("\{location}.upArgs must be an array")
  }
}

///|
fn command_field(
  value : Json,
  location : String,
) -> Array[String]? raise ConfigError {
  match field(value, "command") {
    None => None
    Some(Json::Array(items)) => {
      guard items.length() > 0 else {
        raise InvalidConfig("\{location}.command must be a nonempty array")
      }
      let command = items.mapi((index, item) => {
        match item {
          Json::String(text) => {
            guard !text.contains("\u0000") && (index != 0 || text != "") else {
              raise InvalidConfig(
                "\{location}.command[\{index}] must not contain NUL or have an empty executable",
              )
            }
            text
          }
          _ =>
            raise InvalidConfig(
              "\{location}.command[\{index}] must be a string",
            )
        }
      })
      Some(command)
    }
    _ => raise InvalidConfig("\{location}.command must be an array of strings")
  }
}

///|
pub fn interpolate(
  value : String,
  lookup : (String) -> String?,
///|
pub let usage : String = "Usage: orca-env-devsy <status|stop [--force]|resume> --provider <name> [--jobs <n>]\n       orca-env-devsy recipe <create|resume|suspend|destroy|recover|restart>\n       orca-env-devsy <recover|restart>\n"

///|
priv struct BulkOptions {
  provider : String
  jobs : Int32
  force : Bool
}

///|
fn bulk_options(mode : String, args : Array[String]) -> BulkOptions raise {
  let mut provider = None
  let mut jobs = 4
  let mut force = false
  let mut i = 0
  while i < args.length() {
    match args[i] {
      "--provider" if i + 1 < args.length() && provider is None => {
        i += 1
        provider = Some(args[i])
      }
      "--jobs" if i + 1 < args.length() => {
        i += 1
        jobs = @string.parse_int(args[i])
      }
      "--force" if mode == "stop" && !force => force = true
      _ => raise AdapterError("Invalid bulk option: " + args[i])
    }
    i += 1
  }
  guard provider is Some(provider) &&
    valid_context(provider) &&
    jobs > 0 &&
    jobs <= 64 else {
    raise AdapterError(
      "--provider is required; --jobs must be between 1 and 64",
    )
  }
  { provider, jobs, force, }
}

///|
async fn observe_activity(state : Json) -> Json {
  let directory = required(state, "tunnelDirectory")
  let pairing = if @fs.exists(directory + "/pairing-code") {
    @fs.read_file(directory + "/pairing-code").text()
  } else {
    ""
  }
  let script = activity_command(state)
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (output, reader) = @process.read_from_process()
  defer output.close()
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  @async.with_timeout(30000, async fn() {
    @async.with_task_group(async fn(group) {
      let child = @process.spawn(
        group,
        "ssh",
        ssh_args(state, services=false) + [script],
        stdin=input,
        stdout=reader,
        stderr=sink,
      )
      let reading = group.spawn(async fn() {
        let buffer = @buffer.Buffer()
        let bytes = FixedArray::make(4096, b'\x00')
        while true {
          let count = output.read(bytes)
          if count == 0 {
            break
          }
          guard buffer.length() + count <= 4194304 else {
            raise AdapterError("Activity response too large")
          }
          buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
        }
        @utf8.decode(buffer.to_bytes())
      })
      let payload : Json = { "pairingCode": pairing }
      writer.write(payload.stringify())
      writer.close()
      guard child.wait() == 0 else {
        raise AdapterError("Remote activity probe failed")
      }
      let value = @json.parse(reading.wait())
      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
        raise AdapterError("Invalid activity response")
      }
      value
    })
  })
}

///|
fn activity_command(state : Json) -> String {
