  await persistent.close();
  const receipt = JSON.stringify({ schemaVersion: 1, recipeResult: persistent.runtime.recipeResult });
  await run([adapter, "recipe", "suspend"], { env, timeout: budgets.lifecycle, input: receipt });
  await measure("recreate-persistent-server", budgets.provision, () => d(["workspace", "up", state.workspaceId as string, "--recreate", "--ide-launch", "skip", "--mount", `type=volume,source=${volume},target=/workspaces/.orca`]), persistent.index);
  await run([adapter, "recipe", "recover"], { env, timeout: budgets.lifecycle, input: receipt });
  const checkPersistence = async () => {
    await d(["workspace", "ssh", state.workspaceId as string, "--start-services=false", "--agent-forwarding=false", "--user", state.user as string, "--command", `set -eu; test ! -e "$HOME/e2e-volatile"; test "$(cat /workspaces/.orca/.profile/e2e-marker)" = preserved; test "$(cat ${quote(worktreePath + "/worktree-usable.txt")})" = usable; git -C ${quote(worktreePath)} rev-parse --is-inside-work-tree`]);
    await persistent.checkClient();
    const response = await orca!.call<{ ok: boolean; result: { worktrees: { id: string; path: string }[] } }>("runtimeEnvironments", "call", { selector: persistent.runtime.runtimeEnvironmentId, method: "worktree.list", params: { repo: persistent.path }, timeoutMs: budgets.operation });
    assert(response.ok);
    assert(response.result.worktrees.some(w => w.id === persistent.runtime.workspaceId && w.path === worktreePath), "Remote profile must retain the existing worktree registration");
  };
  await checkPersistence();
  workspaces[workspaces.indexOf(persistent)] = { ...persistent, check: checkPersistence, close: async () => {} };
  console.log("PASS devcontainer recreation: checkout, worktree, profile and existing client registration");
  beginPhase("destroy");
  const live = [...workspaces];
  for (const current of workspaces) {
    await current.close();
    const cleaned: Runtime = await orca.call<Runtime>("ephemeralVm", "cleanup", { runtimeId: current.runtime.id });
    assert.equal(cleaned.status, "cleaned");
///|
fn orca_storage_args(state : Json) -> Array[String] {
  match field(state, "orcaVolume") {
    Some(Json::String(volume)) =>
      ["--mount", "type=volume,source=" + volume + ",target=/workspaces/.orca"]
    _ => []
  }
}

///|
async fn prepare_orca_storage(state : Json) -> Unit {
  guard field(state, "orcaVolume") is Some(Json::String(volume)) else { return }
  save_diagnostic(
    "orca-storage",
    "started",
    source=Storage(volume, required(state, "projectRoot")),
  )
  let user = required(state, "user")
  let uid = required(state, "workspaceUid")
  let script = "set -eu; root=/workspaces/.orca; " +
    "grep -q ' /workspaces/.orca ' /proc/self/mountinfo || { echo 'Orca storage mount is missing' >&2; exit 1; }; " +
    "if test -f \"$root/.owner\"; then test \"$(cat \"$root/.owner\")\" = " +
    quote(uid) +
    "; else test -z \"$(find \"$root\" -mindepth 1 -maxdepth 1 ! -name lost+found -print -quit)\" || { echo 'Orca storage has unowned contents' >&2; exit 1; }; printf '%s' " +
    quote(uid) +
    " > \"$root/.owner\"; fi; " +
    "chown \"$(id -u " +
    quote(user) +
    "):\"\"$(id -g " +
    quote(user) +
    ")\" \"$root\"; chmod 700 \"$root\""
  ignore(
    devsy(
      state,
      [
        "workspace",
        "ssh",
        required(state, "workspaceId"),
        "--start-services=false",
        "--agent-forwarding=false",
        "--user",
        "root",
        "--command",
        script,
      ],
      "orca-storage",
    ),
  )
  save_diagnostic(
    "orca-storage",
    "success",
    source=Storage(volume, required(state, "projectRoot")),
  )
}

///|
fn remote_orca_cli(state : Json) -> String {
  (if field(state, "orcaVolume") is Some(_) {
    "ORCA_USER_DATA_PATH=/workspaces/.orca/.profile "
  } else {
    ""
  }) +
  "ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" \"$HOME/.local/share/orca-env-devsy/orca/current/resources/app.asar/out/cli/index.js\" "
}

