const (
	debugFlag          = " --debug"
	defaultExitTimeout = 5 * time.Second
	maxRetrySteps      = 10
	retryDuration      = 1 * time.Second
	retryFactor        = 2.0
	retryJitter        = 0.1
)

// RunServicesOptions contains all options for running services.
type RunServicesOptions struct {
	DevsyConfig                    *config.Config
	ContainerClient                *ssh.Client
	User                           string
	ForwardPorts                   bool
	ExtraPorts                     []string
	PlatformOptions                *devsy.PlatformOptions
	Workspace                      *provider.Workspace
	ConfigureDockerCredentials     bool
	ConfigureGitCredentials        bool
	ConfigureGitSSHSignatureHelper bool
	GitSSHSigningKey               string
	// ExtraListeners holds pre-bound listeners keyed by "host:port" so the
	// helper can skip net.Listen and avoid a probe-to-listen TOCTOU race.
	ExtraListeners map[string]net.Listener
	// DisableIdleTimeout forces a zero idle-shutdown duration regardless of
	// the EXIT_AFTER_TIMEOUT context option. Used by callers reaped
	// out-of-band rather than by idle activity.
	DisableIdleTimeout bool
}

// getExitAfterTimeout resolves the per-forward idle-shutdown duration.
// Returns 0 (no idle shutdown) when disableIdleTimeout is set or when
// EXIT_AFTER_TIMEOUT is not true in the active context.
func getExitAfterTimeout(devsyConfig *config.Config, disableIdleTimeout bool) time.Duration {
	if disableIdleTimeout {
		return 0
	}
	if devsyConfig.ContextOption(config.ContextOptionExitAfterTimeout) != config.BoolTrue {
		return 0
	}
	return defaultExitTimeout
}

// createForwarder creates a port forwarder if port forwarding is enabled.
func createForwarder(
	opts RunServicesOptions,
	forwardedPorts []string,
	resolver PortAttributeResolver,
) netstat.Forwarder {
	if !opts.ForwardPorts {
		return nil
	}
	ports := append([]string{}, forwardedPorts...)
	ports = append(ports, fmt.Sprintf("%d", openvscode.DefaultVSCodePort))
	ports = append(ports, fmt.Sprintf("%d", codeserver.DefaultCodeServerPort))
	return newForwarder(opts.ContainerClient, ports, resolver)
}

// tunnelServerParams contains parameters for running the tunnel server.
type tunnelServerParams struct {
	opts         RunServicesOptions
	stdoutReader *os.File
	stdinWriter  *os.File
	forwarder    netstat.Forwarder
	errChan      chan error
}

// runTunnelServer runs the tunnel server in a goroutine.
func runTunnelServer(ctx context.Context, cancel context.CancelFunc, p tunnelServerParams) {
	defer cancel()
	defer func() { _ = p.stdoutReader.Close() }()
	defer func() { _ = p.stdinWriter.Close() }()
	err := tunnelserver.RunServicesServer(
		ctx,
		p.stdoutReader,
		p.stdinWriter,
		p.opts.ConfigureGitCredentials,
		p.opts.ConfigureDockerCredentials,
		p.forwarder,
		p.opts.Workspace,
		tunnelserver.WithPlatformOptions(p.opts.PlatformOptions),
	)
	if err != nil {
		p.errChan <- fmt.Errorf("run tunnel server: %w", err)
	}
	close(p.errChan)
}

// addGitSSHSigningKey adds SSH signing key to command if configured.
// When explicitKey is set (from --git-ssh-signing-key flag), it takes
// precedence over the host's .gitconfig. This ensures signing works
// even when user.signingkey is not in the host git configuration.
func addGitSSHSigningKey(
	ctx context.Context,
	command string,
	explicitKey string,
	workingDir string,
) string {
	userSigningKey := explicitKey
	if userSigningKey == "" {
		format, extracted, err := gitsshsigning.ExtractGitConfiguration(ctx, workingDir)
		if err != nil {
			log.Debugf("failed to extract git configuration: %v", err)
			return command
		}
		if format != gitsshsigning.GPGFormatSSH || extracted == "" {
			return command
		}
		userSigningKey = extracted
	}
	encodedKey := base64.StdEncoding.EncodeToString([]byte(userSigningKey))
	command += fmt.Sprintf(" --git-user-signing-key %s", encodedKey)
	return command
}

// buildCredentialsCommand builds the credentials server command.
func buildCredentialsCommand(ctx context.Context, opts RunServicesOptions) string {
	command := fmt.Sprintf(
		"%s internal agent container credentials-server --user %s",
		shellescape.Quote(config.ContainerDevsyHelperLocation),
		shellescape.Quote(opts.User),
	)
	if opts.ConfigureGitCredentials {
		command += " --configure-git-helper"
	}
	if opts.ConfigureGitSSHSignatureHelper {
		workingDir := ""
		if opts.Workspace != nil {
			workingDir = opts.Workspace.Source.LocalFolder
		}
		command = addGitSSHSigningKey(ctx, command, opts.GitSSHSigningKey, workingDir)
	}
	if opts.ConfigureDockerCredentials {
		command += " --configure-docker-helper"
	}
	if opts.ForwardPorts {
		command += " --forward-ports"
	}
	if log.DebugEnabled() {
		command += debugFlag
	}
	return command
}

// runServicesIteration performs one iteration of the retry loop.
func runServicesIteration(
	ctx context.Context,
	opts RunServicesOptions,
	forwardedPorts []string,
	resolver PortAttributeResolver,
) error {
	stdoutReader, stdoutWriter, err := os.Pipe()
	if err != nil {
		return err
	}
	defer func() { _ = stdoutWriter.Close() }()

	stdinReader, stdinWriter, err := os.Pipe()
	if err != nil {
		_ = stdoutReader.Close()
		return err
	}
	defer func() { _ = stdinReader.Close() }()

	cancelCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	forwarder := createForwarder(opts, forwardedPorts, resolver)

	errChan := make(chan error, 1)
	go runTunnelServer(cancelCtx, cancel, tunnelServerParams{
		opts:         opts,
		stdoutReader: stdoutReader,
		stdinWriter:  stdinWriter,
		forwarder:    forwarder,
		errChan:      errChan,
	})
		return ""
	}

	return result.MergedConfig.WorkspaceFolder
}

type startServicesOptions struct {
	ConfigureDockerCredentials     bool
	ConfigureGitCredentials        bool
	ConfigureGitSSHSignatureHelper bool
	GitSSHSigningKey               string
}

func (cmd *SSHCmd) startServices(
	ctx context.Context,
	devsyConfig *config.Config,
	containerClient *ssh.Client,
	workspace *provider.Workspace,
	opts startServicesOptions,
) {
	if cmd.User != "" {
